
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_sb98_2c_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_sb98_2c", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.451589427558902e+00, -3.385766123062704e+00, -3.293559699995685e+00, -3.165900371114794e+00, -2.992126879148301e+00, -2.761319043397742e+00, -2.465509619558475e+00, -2.105688264977327e+00, -1.700202886804862e+00, -1.286668949878619e+00, -8.813197727601079e-01, -5.974752061014718e-01, -5.165127512974970e-01, -4.259897105406420e-01, -3.074792764725484e-01, -1.917184638563211e-01, -1.118643532549000e-01, -4.947212739478465e-02, -1.181628215018631e-02, -1.385202905322580e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


